import {execFileSync} from 'node:child_process';import {DatabaseSync} from 'node:sqlite';import {appendFileSync} from 'node:fs';
const db=new DatabaseSync('/opt/p003/archive-t5-20261117/p003-t5-50x6000-01/analytics.db',{readOnly:true});db.exec('PRAGMA cache_size=-65536');
const out='/opt/p003/archive-t5-20261117/rollup-profile-03.jsonl';const emit=x=>appendFileSync(out,JSON.stringify(x)+'\n');
const where=" FROM analytics_rollup_fact WHERE dimension='occurred' AND day='2026-11-17'";
emit({plan:db.prepare('EXPLAIN QUERY PLAN SELECT *'+where+' ORDER BY device_key,received_at_ms,id_digest').all()});
for(const [name,sql] of [['rowid-reordered',"SELECT device_key,event_name,session_digest,clock_suspicious,semantic_json,received_at_ms FROM analytics_rollup_fact WHERE rowid IN (SELECT rowid FROM analytics_rollup_fact WHERE dimension='occurred' AND day='2026-11-17') ORDER BY rowid"]]){
 db.exec('PRAGMA shrink_memory');execFileSync('python3',['-c',"import os;f=os.open('/opt/p003/archive-t5-20261117/p003-t5-50x6000-01/analytics.db',os.O_RDONLY);os.posix_fadvise(f,0,0,os.POSIX_FADV_DONTNEED);os.close(f)"]);let rows=0,total=0;const t=performance.now();for(const r of db.prepare(sql).iterate()){rows++;total+=r.n??1;if(name!=='grouped')JSON.parse(r.semantic_json);}emit({name,rows,total,ms:performance.now()-t,rss:process.memoryUsage().rss});
}db.close();
